import airline.*;import java.util.List;import java.nio.file.Path;
public class Study {
 public static Object plane(String fixtureId,int kind,int seats,double tonnes,double range,double fuel){return kind==0?new Passenger(fixtureId,seats,tonnes,range,fuel):new Cargo(fixtureId,seats,tonnes,range,fuel);}
 public static Object company(List<?>planes){return new Airline(planes);}public static List<?>planes(Object company){return ((Airline)company).planes();}public static List<?>ordered(Object company){return ((Airline)company).ordered();}public static List<?>find(Object company,double lo,double hi){return ((Airline)company).find(lo,hi);}
 public static int seats(Object plane){return ((Plane)plane).seats();}public static int totalSeats(Object company){return ((Airline)company).totalSeats();}public static double tonnes(Object plane){return ((Plane)plane).tonnes();}public static double range(Object plane){return ((Plane)plane).range();}public static double fuel(Object plane){return ((Plane)plane).fuel();}public static double totalTonnes(Object company){return ((Airline)company).totalTonnes();}public static String fixtureId(Object plane){return ((Plane)plane).id();}public static int kind(Object plane){return ((Plane)plane).kind();}
 public static void save(Object company,Path location)throws Exception{new Connector().save((Airline)company,location);}public static Object load(Path location)throws Exception{return new Connector().load(location);}public static void updateSeats(Path location,String fixtureId,int seats)throws Exception{new Connector().updateSeats(location,fixtureId,seats);}
}
